const o={get:t=>{const e=localStorage.getItem(t);return{[t]:e?JSON.parse(e):null}},set:t=>{Object.keys(t).forEach(e=>{localStorage.setItem(e,JSON.stringify(t[e]))})},remove:t=>{localStorage.removeItem(t)}};async function c(t){return o.remove(t)}async function s(t,e){try{return typeof e=="object"&&(e=JSON.parse(JSON.stringify(e))),o.set({[t]:e})}catch{}}async function n(t){try{return(await o.get(t))[t]}catch{}}async function a(t){const e={};for(const r of t)e[r]=await n(r);return e}export{n as getItem,a as getItems,c as removeItem,s as setItem};
